import java.util.*;

public class Main {
    int minFlips(String s) {
        int n = s.length();
        int best = n;
        String doubled = s + s;
        for (int start = 0; start < n; start++) {                                 // try every possible rotation as a starting point
            String window = doubled.substring(start, start + n);
            int mismatch1 = 0, mismatch2 = 0;
            for (int i = 0; i < n; i++) {
                char expected1 = (i % 2 == 0) ? '0' : '1';
                char expected2 = (i % 2 == 0) ? '1' : '0';
                if (window.charAt(i) != expected1) mismatch1++;
                if (window.charAt(i) != expected2) mismatch2++;
            }
            best = Math.min(best, Math.min(mismatch1, mismatch2));
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minFlips("1110"));
    }
}

