def min_flips(s):
    n = len(s)
    doubled = s + s
    mismatch1 = 0                                                            # mismatches against pattern starting '0': 0,1,0,1,...
    mismatch2 = 0                                                            # mismatches against pattern starting '1': 1,0,1,0,...
    best = n
    for i, c in enumerate(doubled):
        expected1 = '0' if i % 2 == 0 else '1'
        expected2 = '1' if i % 2 == 0 else '0'
        if c != expected1:
            mismatch1 += 1
        if c != expected2:
            mismatch2 += 1
        if i >= n:
            leave = i - n
            leave_char = doubled[leave]
            leave_expected1 = '0' if leave % 2 == 0 else '1'
            leave_expected2 = '1' if leave % 2 == 0 else '0'
            if leave_char != leave_expected1:
                mismatch1 -= 1                                               # the character leaving the window is removed from the running mismatch count
            if leave_char != leave_expected2:
                mismatch2 -= 1
        if i >= n - 1:
            best = min(best, mismatch1, mismatch2)
    return best


if __name__ == "__main__":
    print(min_flips("1110"))

